"""Check the foreign ARM64 vDSO and the three ordinary Gazelle entry points."""

from hashlib import sha256
import json
import os
import platform
import subprocess
import sys
import xml.etree.ElementTree as ET

import downstream_llvm as qa

BASE = "42ac721046639db7753e69f9794b296390ef4bb4"
FIX = "b8e467cbdab3db4a9e9c22442f98e4bee0fdcbdd"
NAMES = ("gazelle", "gazelle_check", "gazelle_fix")
SENTINEL = "fork_gazelle_sentinel.go"
CASES = qa.REPORT["cases"]


def run(case, name, op, *args, timeout=600):
    cmd = [str(qa.AREA / "bazelisk"), "--nosystem_rc", "--nohome_rc", "--host_jvm_args=-Xmx4g",
           op, "--lockfile_mode=off"]
    if op != "query":
        cmd.append("--jobs=3")
    try:
        p = subprocess.run([*cmd, *args], cwd=qa.SRC, capture_output=True, timeout=timeout)
        code, out, err = p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired as exc:
        code, out, err = 124, exc.stdout or b"", exc.stderr or b""
    row = case[name] = {"exit": code, "stdoutSHA256": sha256(out).hexdigest(), "stderrSHA256": sha256(err).hexdigest()}
    if code:
        row["diagnostics"] = [s.replace(str(qa.SRC), "<source>")[:400] for s in err.decode(errors="replace").splitlines()
                              if s.startswith("ERROR:") or "Error in fail" in s][:5]
    qa.save()
    return row, out


def foreign():
    case = CASES["foreign"] = {"source": FIX}
    qa.CONSUMER.mkdir()
    module = ('module(name = "downstream")\nbazel_dep(name = "gvisor", version = "0.0.1")\n'
              f'local_path_override(module_name = "gvisor", path = {json.dumps(str(qa.SRC))})\n')
    (qa.CONSUMER / "MODULE.bazel").write_text(module)
    (qa.CONSUMER / "BUILD.bazel").write_text("")
    (qa.CONSUMER / ".bazelversion").write_text("9.3.1\n")
    case["consumerModule"] = module.replace(str(qa.SRC), "<source>")
    qa.save()
    row, out = qa.bazel(case, "metadata", "query", "set(@gvisor//:license @gvisor//:sandbox)",
                        "--output=xml", "--xml:default_values")
    if row["exit"] == 0:
        xml = ET.fromstring(out)
        row["labels"] = [e.get("name") for e in xml if e.get("name")]
    qa.plan(case)
    qa.build(case)
    qa.save()
    subprocess.run([str(qa.AREA / "bazelisk"), "--nosystem_rc", "--nohome_rc", "--noworkspace_rc", "shutdown"],
                   cwd=qa.CONSUMER, capture_output=True, timeout=90)


def original_outputs(case, source):
    qa.git("switch", "--quiet", "--detach", source)
    case.update(source=source, scripts={})
    qa.save()
    view, out = run(case, "gopath", "cquery", "--output=files", "//:gopath", timeout=700)
    view["zip"] = any(s.endswith("/bin/gopath.zip") for s in out.decode(errors="replace").splitlines())
    view, out = run(case, "metadata", "query", "set(//:license //:sandbox //:nogo_config //:release //:github_actions_test)", "--output=label")
    view["labels"] = sorted(s for s in out.decode(errors="replace").splitlines() if s.startswith("//:"))
    built, _ = run(case, "tools", "build", *["//:" + n + suffix for n in NAMES for suffix in ("", "-runner")], timeout=1000)
    if built["exit"] == 0:
        for n in NAMES:
            for f in (n, n + "-runner.bash"):
                path = qa.SRC / "bazel-bin" / f
                if path.is_file() and os.access(path, os.X_OK):
                    raw = path.read_bytes()
                    # Gazelle's only intended template change is the source label in a comment.
                    normalized = b"\n".join(line.replace(b"//tools:", b"//:") if line.startswith(b"#") and b"Generated by" in line else line
                                           for line in raw.split(b"\n"))
                    case["scripts"][f] = {"sha256": sha256(raw).hexdigest(), "normalized": sha256(normalized).hexdigest()}
    qa.save()


def behavior(case):
    generic, _ = run(case, "generic", "run", "//:gazelle", "--", "-mode=diff", "-index=none", "-r=false", "pkg/bits")
    clean, _ = run(case, "clean", "run", "//:gazelle_check")
    injected = qa.SRC / "pkg/bits" / SENTINEL
    buildfile = qa.SRC / "pkg/bits/BUILD"
    orig = buildfile.read_bytes()
    assert not injected.exists()
    try:
        injected.write_text("package bits\n\nconst forkGazelleSentinel = 1\n")
        drift, out = run(case, "drift", "run", "//:gazelle_check")
        drift["added"] = any(s.lstrip().startswith("+") and SENTINEL in s for s in out.decode(errors="replace").splitlines())
        fix, _ = run(case, "fix", "run", "//:gazelle_fix")
        fix["included"] = SENTINEL.encode() in buildfile.read_bytes() and buildfile.read_bytes() != orig
        fix["changed"] = qa.git("diff", "--name-only").splitlines()[:20]
        final, _ = run(case, "afterFix", "run", "//:gazelle_check")
    finally:
        injected.unlink(missing_ok=True)
        qa.git("restore", "--worktree", "--", "pkg/bits/BUILD")
    case["behavior"] = (generic["exit"] == clean["exit"] == fix["exit"] == final["exit"] == 0 and
                        drift["exit"] != 0 and drift["added"] and fix["included"] and fix["changed"] == ["pkg/bits/BUILD"])
    qa.save()


def main():
    assert qa.git("rev-parse", "HEAD^") == FIX and qa.git("rev-parse", FIX + "^") == BASE
    assert qa.git("rev-parse", BASE + ":LICENSE") == qa.git("rev-parse", FIX + ":LICENSE")
    assert platform.machine() == "x86_64"
    qa.git("switch", "--quiet", "--detach", FIX)
    try:
        foreign()
    except (AssertionError, OSError, ValueError, subprocess.SubprocessError) as exc:
        CASES["foreign"]["collectionError"] = type(exc).__name__
        qa.save()
    for name, rev in (("old", BASE), ("new", FIX)):
        case = CASES[name] = {}
        try:
            original_outputs(case, rev)
            if name == "old" and case["tools"]["exit"] == 0:
                run(case, "clean", "run", "//:gazelle_check")
            if name == "new" and case["tools"]["exit"] == 0:
                behavior(case)
        except (AssertionError, OSError, ValueError, subprocess.SubprocessError) as exc:
            case["collectionError"] = type(exc).__name__
            qa.save()
    old, new, f = CASES["old"], CASES["new"], CASES["foreign"]
    qa.REPORT["sameScripts"] = (len(old.get("scripts", {})) == 6 and
          {k: v["normalized"] for k, v in old["scripts"].items()} == {k: v["normalized"] for k, v in new.get("scripts", {}).items()})
    qa.REPORT["passed"] = (qa.REPORT["sameScripts"] and f.get("linkedARM64", False) and
                           f.get("metadata", {}).get("exit") == 0 and new.get("behavior", False) and
                           all(c.get("gopath", {}).get("zip") and c["gopath"]["exit"] == 0 for c in (old, new)) and
                           old["metadata"].get("labels") == new["metadata"].get("labels") and len(new["metadata"]["labels"]) == 5)
    qa.save()
    return int(not qa.REPORT["passed"])


if __name__ == "__main__":
    sys.exit(main())
